% Number and percentage of displacement vectors kept after the filtering
% step (-X component, 0.3-8 um), relative to the valid (non-NaN) vectors,
% and median of the filtered displacements, for each position. Diagnostic
% columns: percentage of vectors towards and away from the magnet, and of
% vectors towards the magnet below and above the filter limits.
%
% Input: tp_01.mat files generated by TFMLAB (edit the paths below).
% Output: percent_kept.xlsx

clear
clc

%% Files: {group, label, path}
% Write here the paths of all the tp_01.mat files (one line per position)
files = {
    'PEG-W 1.2%', 'Sample 1 - pos1', 'path/to/peg12_sample1_pos1/D_2_displacements/beads/tp_01.mat'
    'PEG-W 1.2%', 'Sample 1 - pos2', 'path/to/peg12_sample1_pos2/D_2_displacements/beads/tp_01.mat'
    'PEG-W 1.2%', 'Sample 1 - pos3', 'path/to/peg12_sample1_pos3/D_2_displacements/beads/tp_01.mat'
    % ... (remaining samples of PEG-W 1.2%)
    'PEG-W 1.5%', 'Sample 1 - pos1', 'path/to/peg15_sample1_pos1/D_2_displacements/beads/tp_01.mat'
    % ... (remaining samples of PEG-W 1.5%)
    'Control',    'pos1',            'path/to/control_pos1/D_2_displacements/beads/tp_01.mat'
    'Control',    'pos2',            'path/to/control_pos2/D_2_displacements/beads/tp_01.mat'
    'Control',    'pos3',            'path/to/control_pos3/D_2_displacements/beads/tp_01.mat'
};

%% Filter limits (um)
minVal = 0.3;
maxVal = 8;

%% Number and percentage of vectors kept after the filtering step
nFiles   = size(files, 1);
nTotal   = zeros(nFiles, 1);   % all vectors of the field
nValid   = zeros(nFiles, 1);   % vectors that are not NaN
nTowards = zeros(nFiles, 1);   % x < 0 (towards the magnet), any magnitude
nAway    = zeros(nFiles, 1);   % x > 0 (away from the magnet)
nBelow   = zeros(nFiles, 1);   % towards the magnet but below minVal
nAbove   = zeros(nFiles, 1);   % towards the magnet but above maxVal
nKept    = zeros(nFiles, 1);   % vectors kept after the filter
medX     = NaN(nFiles, 1);

for i = 1:nFiles
    S = load(files{i, 3});
    X = S.dispField.X(:);

    nTotal(i) = numel(X);

    X = X(~isnan(X));                       % remove NaNs
    nValid(i) = numel(X);
    nAway(i)  = sum(X > 0);

    X = -X(X < 0);                          % -X component (towards the magnet)
    nTowards(i) = numel(X);
    nBelow(i)   = sum(X < minVal);
    nAbove(i)   = sum(X > maxVal);

    X = X(X >= minVal & X <= maxVal);       % filter step
    nKept(i) = numel(X);

    if ~isempty(X)
        medX(i) = median(X);
    end
end

% percentages of the valid (non-NaN) vectors
pctKept    = 100 * nKept    ./ nValid;
pctTowards = 100 * nTowards ./ nValid;
pctAway    = 100 * nAway    ./ nValid;
pctBelow   = 100 * nBelow   ./ nValid;
pctAbove   = 100 * nAbove   ./ nValid;

%% Table with all files
T = table(string(files(:,1)), string(files(:,2)), nTotal, nValid, nKept, pctKept, medX, ...
    pctTowards, pctAway, pctBelow, pctAbove, ...
    'VariableNames', {'Group','File','N_total','N_valid','N_kept','Percent_kept','Median_um', ...
    'Percent_towards','Percent_away','Percent_towards_below_min','Percent_towards_above_max'});
disp(T)

%% Summary per group
groups = unique(string(files(:,1)), 'stable');
fprintf('\n=== Percentage of vectors kept after filtering ===\n')
for g = 1:numel(groups)
    idx = T.Group == groups(g);
    p = T.Percent_kept(idx);
    fprintf('%s: median = %.1f %%, mean = %.1f +/- %.1f %%, range = %.1f-%.1f %% (n = %d)\n', ...
        groups(g), median(p), mean(p), std(p), min(p), max(p), numel(p))
end

%% Save
writetable(T, 'percent_kept.xlsx')
